    {
      "compound": "Phallisacin and phallisin (phallotoxins)",
      "amount": "0.02 mg/g dry weight",
      "effect": "Actin-binding peptides that are hepatotoxic when injected but largely inactive when eaten."
    },
    {
      "compound": "Viroidin and other virotoxins (monocyclic peptides)",
      "amount": "unknown",
      "effect": "Bind actin and cause rapid liver damage in animals after injection, with little effect by the oral route."
    },
    {
      "compound": "Phallolysin (hemolytic protein)",
      "amount": "unknown",
